def plausible_person(name: str) -> bool:
    n = norm_name(name)
    if len(n) < 5 or len(n) > 60:
        return False
    parts = n.split()
    if len(parts) < 2 or len(parts) > 4:
        return False
    if any(len(p) < 3 for p in parts):
        return False
    junk = (
        "committee", "board", "director", "chairman", "trial", "continued", "page",
        "kennel", "farm", "terriers", "maryland", "virginia", "image", "damage",
    )
    if any(j in n.lower() for j in junk):
        return False
    if sum(c.isalpha() for c in n) < 6:
        return False
    # reject OCR garbage with too many non-letters relative to length
    if sum(1 for c in n if not (c.isalnum() or c in " -'.")) > 2:
        return False
    return True

