    ]


def _looks_like_html(raw: bytes) -> bool:
    if not raw or len(raw) < 200:
        return False
    if raw[:2] == b"\x1f\x8b":
        try:
            import gzip

            raw = gzip.decompress(raw)
        except Exception:
            return False
    sample = raw[:2000].decode("utf-8", errors="ignore").lower()
    return "<html" in sample or "<table" in sample or "<!doctype" in sample

