#!/usr/bin/env python3
"""Export certificate / NHC / kennel pages from 49n1 and scan all vols for section pages."""
from __future__ import annotations

from pathlib import Path
import fitz
import re

ROOT = Path(r"c:\Users\mw\OneDrive - timberwilde.net\repos\jrtca_results\True Grit")
OUT = Path(r"c:\Users\mw\OneDrive - timberwilde.net\repos\jrtca_results\truegrit_extract")

VOL_YEAR = {47: 2023, 48: 2024, 49: 2025, 50: 2026}


def dump_pages(pdf: Path, pages: list[int], tag: str) -> None:
    doc = fitz.open(pdf)
    for i in pages:
        if i < 1 or i > doc.page_count:
            continue
        text = doc.load_page(i - 1).get_text("text")
        (OUT / f"{tag}_p{i:03d}.txt").write_text(text, encoding="utf-8", errors="replace")


def find_sections(pdf: Path) -> dict:
    doc = fitz.open(pdf)
    markers = {
        "board": re.compile(r"BOARD OF DIRECTORS\s*:", re.I),
        "state_reps": re.compile(r"JRTCA State Representatives|STATE REPRESENTATIVES", re.I),
        "new_reg": re.compile(r"^New Registrations\s*$|NEW REGISTRATIONS", re.M | re.I),
        "kennel": re.compile(r"Kennel Prefix", re.I),
        "trial_cert": re.compile(r"Trial Certificates?\b", re.I),
        "nhc": re.compile(r"Natural Hunting Certificate", re.I),
        "period": re.compile(r"represent the period", re.I),
    }
    hits = {k: [] for k in markers}
    for i in range(doc.page_count):
        t = doc.load_page(i).get_text("text")
        for k, rx in markers.items():
            if rx.search(t):
                hits[k].append(i + 1)
    return {"pages": doc.page_count, **hits}


def main() -> None:
    OUT.mkdir(exist_ok=True)
    # dump more of 49n1 around certificates
    pdf49 = ROOT / "tgrit_49n1_issue.pdf"
    dump_pages(pdf49, list(range(66, 80)), "49n1")
    dump_pages(pdf49, [36, 37, 38, 57, 58, 68], "49n1")
    print("=== section map all vols ===")
    for pdf in sorted(ROOT.glob("tgrit_4[789]*_issue.pdf")) + sorted(ROOT.glob("tgrit_50*_issue.pdf")):
        m = re.search(r"tgrit_(\d+)n(\d+)", pdf.name)
        if not m:
            continue
        vol, num = int(m.group(1)), int(m.group(2))
        year = VOL_YEAR.get(vol)
        info = find_sections(pdf)
        print(f"{pdf.name} year={year} pages={info['pages']}")
        for k in ("board", "state_reps", "new_reg", "kennel", "trial_cert", "nhc", "period"):
            print(f"  {k}: {info[k][:8]}")


if __name__ == "__main__":
    main()

