def _header_col_starts(header_words: list, labels: list[str]) -> dict[str, float] | None:
    """Map logical column label -> x0 from a 'Name of Terrier Owner Judge …' header row."""
    # Find first "Name" then subsequent Owner/Judge/Quarry|Trial labels to the right
