def _midpoint_bounds(starts: dict[str, float], order: list[str]) -> list[tuple[str, float, float]]:
    """Return (label, x_min, x_max) using midpoints between column starts."""
    xs = [(lab, starts[lab]) for lab in order if lab in starts]
    xs.sort(key=lambda p: p[1])
    bounds = []
    for i, (lab, x) in enumerate(xs):
        left = 0.0 if i == 0 else (xs[i - 1][1] + x) / 2
        right = 1e9 if i == len(xs) - 1 else (x + xs[i + 1][1]) / 2
        bounds.append((lab, left, right))
