        right = 1e9 if i == len(xs) - 1 else (x + xs[i + 1][1]) / 2
        bounds.append((lab, left, right))
    return bounds


def _assign_by_bounds(ws: list, bounds: list[tuple[str, float, float]]) -> dict[str, str]:
