#!/usr/bin/env python3
"""Systematically map True Grit certificate/registration table geometry."""
from __future__ import annotations

from collections import defaultdict
from pathlib import Path
import fitz

PDF = Path(r"True Grit/tgrit_47n1_issue.pdf")


def lines_of(page, y_tol=2.5):
    buckets: dict[float, list] = {}
    for w in page.get_text("words"):
        y = w[1]
        key = None
        for k in buckets:
            if abs(k - y) <= y_tol:
                key = k
                break
        if key is None:
            key = y
            buckets[key] = []
        buckets[key].append(w)
    return [(y, sorted(ws, key=lambda w: w[0])) for y, ws in sorted(buckets.items())]


def find_table_schemas(lines):
    """Each 'Name' header starts a table; collect Owner/Judge/Quarry|Trial to its right until next Name."""
    tables = []
    for y, ws in lines:
        toks = [(w[0], w[2], w[4]) for w in ws]
        names = [i for i, t in enumerate(toks) if t[2].lower() == "name"]
        if not names:
            continue
        # require 'Owner' somewhere on line
        if not any(t[2].lower() == "owner" for t in toks):
            continue
        for ni, idx in enumerate(names):
            x_right = toks[names[ni + 1]][0] - 1 if ni + 1 < len(names) else 1e9
            cols = {"dog": toks[idx][0]}
            for x0, x1, t in toks[idx + 1 :]:
                if x0 >= x_right:
                    break
                tl = t.lower().rstrip(":")
                if tl in {"owner", "judge", "quarry", "trial", "breeder", "state", "prefix"} and tl not in cols:
                    cols[tl] = x0
            if "owner" not in cols:
                continue
            tables.append({"y": y, "x_left": cols["dog"] - 5, "x_right": x_right, "cols": cols, "raw": toks})
    return tables


def assign(ws, cols, x_left, x_right, tol=10.0):
    ordered = sorted(cols.items(), key=lambda kv: kv[1])
    fields = {k: [] for k, _ in ordered}
    for w in ws:
        if w[0] < x_left or w[0] >= x_right:
            continue
        chosen = ordered[0][0]
        for lab, sx in ordered:
            if w[0] + tol >= sx:
                chosen = lab
            else:
                break
        fields[chosen].append(w[4])
    return {k: " ".join(v).strip() for k, v in fields.items() if v}


def main():
    doc = fitz.open(PDF)
    # NHC page 34 (idx 33) and trial cert page
    for pi in range(doc.page_count):
        page = doc.load_page(pi)
        text = page.get_text("text")
        if "Natural Hunting Certificates Below Ground" not in text and "Trial Certificates" not in text:
            continue
        if "Name of Terrier" not in text:
            continue
        print("\n======== PAGE", pi + 1, "========")
        lines = lines_of(page)
        tables = find_table_schemas(lines)
        print("tables found:", len(tables))
        for t in tables:
            print(" ", {k: round(v, 1) if isinstance(v, float) else v for k, v in t.items() if k != "raw"})
        # parse data rows under each table until next major header or large y jump
        for ti, table in enumerate(tables):
            print(f" -- table {ti} rows --")
            n = 0
            for y, ws in lines:
                if y <= table["y"] + 2:
                    continue
                # stop if we hit another header-ish line far below with different schema
                txt = " ".join(w[4] for w in ws)
                if y > table["y"] + 250:
                    break
                if "Name of Terrier" in txt:
                    break
                if "BRONZE" in txt or "WORKING ACHIEVEMENT" in txt or "TRUE GRIT" in txt and len(ws) < 6:
                    if n:
                        break
                fields = assign(ws, table["cols"], table["x_left"], table["x_right"])
                if not fields.get("dog") or "dog" not in fields:
                    continue
                if len(fields.get("dog", "")) < 3:
                    continue
                # must have owner-ish
                if "owner" not in fields:
                    continue
                print(f"  y={y:.0f}", fields)
                n += 1
                if n >= 12:
                    break


if __name__ == "__main__":
    main()

