def _header_col_starts(header_words: list, labels: list[str]) -> dict[str, float] | None:
    """Map logical column label -> x0 from a 'Name of Terrier Owner Judge …' header row."""
    # Find first "Name" then subsequent Owner/Judge/Quarry|Trial labels to the right
    starts: dict[str, float] = {}
    # normalize tokens
    toks = [(w[0], w[4].lower().rstrip(":")) for w in sorted(header_words, key=lambda w: w[0])]
    # locate Name (of Terrier)
    name_x = None
    for x, t in toks:
        if t == "name":
            name_x = x
            break
    if name_x is None:
        return None
    starts["dog"] = name_x
    wanted = {lab.lower() for lab in labels if lab != "dog"}
    for x, t in toks:
        if x <= name_x + 5:
            continue
        if t in wanted and t not in starts:
            starts[t] = x
    # alias
    if "trial" in starts and "quarry" not in starts:
        starts["quarry"] = starts["trial"]
    need = {"dog", "owner", "judge"}
    if not need.issubset(starts):
        return None
    return starts


