def _table_matches_kind(table: dict, anchors: list[tuple[float, float]], all_anchors: list[tuple[float, float, str]]) -> bool:
    """Pick tables whose column band is nearest the correct kind title (handles side-by-side titles)."""
    if not anchors:
        return False
    tx = (table["x_left"] + min(table["x_right"], table["cols"]["dog"] + 200)) / 2
    ty = table["y"]
    # Nearest title overall by (dy heavily weighted, then dx)
    best = None
    for y, x, kind_name in all_anchors:
        if y > ty + 5:
            continue  # title must be above the header row
        score = abs(ty - y) * 10 + abs(tx - x)
        if best is None or score < best[0]:
            best = (score, kind_name)
    if best is None:
        # fall back: nearest anchor of this kind above table
        for y, x in anchors:
            if y > ty + 5:
                continue
            score = abs(ty - y) * 10 + abs(tx - x)
            if best is None or score < best[0]:
                best = (score, "SELF")
