def _split_dog_owner_breeder(toks: list[str]) -> tuple[str, str, str] | None:
    """Split token list into dog / owner / breeder using capitalization heuristics."""
    if len(toks) < 3:
        return None
    # Prefer splits where owner and breeder look like people (may include & /)
    best = None
    n = len(toks)
    for i in range(1, n - 1):  # dog ends before i
        for j in range(i + 1, n):  # owner ends before j
            dog = " ".join(toks[:i]).strip()
            owner = _clean_person_field(" ".join(toks[i:j]))
            breeder = _clean_person_field(" ".join(toks[j:]))
            if len(dog) < 3 or len(owner) < 3 or len(breeder) < 2:
                continue
            # dog shouldn't be pure person-looking 2-token if remaining is huge - soft
            score = 0
            if re.search(r"[A-Za-z]", dog):
                score += 1
            if "&" in owner or "/" in owner or plausible_person(owner.split("/")[0].strip()):
                score += 2
            elif re.match(r"^[A-Z]\.", owner) or " " in owner:
                score += 1
            if "&" in breeder or "/" in breeder or plausible_person(breeder.split("/")[0].strip()):
                score += 2
            elif " " in breeder or re.match(r"^[A-Z]\.", breeder):
                score += 1
            # Prefer shorter dog names of 1-4 tokens
            if 1 <= i <= 4:
                score += 1
            if best is None or score > best[0]:
                best = (score, dog, owner, breeder)
    if not best or best[0] < 3:
        return None
    return best[1], best[2], best[3]

