#!/usr/bin/env python3
import json
import re
import urllib.request

UA = {"User-Agent": "Mozilla/5.0 jrtca-results-research"}

URLS = [
    "https://www.jrtcayearbook.com/",
    "https://www.jrtcayearbook.com/wp-sitemap.xml",
    "https://www.jrtcayearbook.com/wp-sitemap-posts-page-1.xml",
    "https://www.jrtcayearbook.com/bronze-medallions/",
    "https://www.jrtcayearbook.com/bronze-medallion/",
    "https://www.jrtcayearbook.com/working-achievement-awards/",
]


def get(url: str) -> str:
    req = urllib.request.Request(url, headers=UA)
    with urllib.request.urlopen(req, timeout=45) as r:
        return r.read().decode("utf-8", "ignore")


def main() -> None:
    for url in URLS:
        print("===", url)
        try:
            t = get(url)
            print("len", len(t))
            hrefs = re.findall(r'href=["\']([^"\']+)["\']', t, re.I)
            for h in hrefs:
                if re.search(r"bronze|nhc|cert|working-achieve|medallion|natural|trial-cert", h, re.I):
                    print(" ", h)
            # sitemap locs
            for loc in re.findall(r"<loc>([^<]+)</loc>", t)[:80]:
                if re.search(r"bronze|working-achieve|cert|nhc|medallion", loc, re.I):
                    print(" LOC", loc)
        except Exception as e:
            print("FAIL", type(e).__name__, e)

    # CDX broad sample
    q = (
        "https://web.archive.org/cdx/search/cdx?url=jrtcayearbook.com/*"
        "&output=json&fl=timestamp,original,statuscode&limit=100"
        "&filter=statuscode:200&from=20150101"
    )
    print("=== CDX sample")
    try:
        req = urllib.request.Request(q, headers=UA)
        with urllib.request.urlopen(req, timeout=90) as r:
            rows = json.load(r)
        interesting = []
        for row in rows[1:]:
            o = row[1].lower()
            if re.search(r"bronze|working-achieve|cert|nhc|medallion|natural", o):
                interesting.append(row)
        print("interesting", len(interesting), "of", len(rows) - 1)
        for row in interesting[:40]:
            print(row)
    except Exception as e:
        print("CDX FAIL", e)


if __name__ == "__main__":
    main()

